    "description": "冬日鹭岛，大批候鸟漂洋过海而来，海湾湿地、红树林间，万鸟翔集；碧波万顷之上，白海豚嬉戏跳跃；五缘湾帆船港、环东海域滨海浪漫线、杏林湾“最美海上自行车道”等“亲海”打卡点游人如织……一幅幅人海和谐图景，见证厦门美丽海湾建设成效。 记者：陈旺 新华社音视频部制作",
    "content": "冬日鹭岛，大批候鸟漂洋过海而来，海湾湿地、红树林间，万鸟翔集；碧波万顷之上，白海豚嬉戏跳跃；五缘湾帆船港、环东海域滨海浪漫线、杏林湾“最美海上自行车道”等“亲海”打卡点游人如织……一幅幅人海和谐图景，见证厦门美丽海湾建设成效。 记者：陈旺 新华社音视频部制作"
