    "description": "中新网昆明11月9日电 (记者 刘冉阳)受强冷空气影响，云南多地出现降雪天气。昆明、曲靖、昭通、丽江、大理等地陆续飘起雪花，部分高海拔山区银装素裹，迎来今冬初雪。",
