    "description": "新华社雅典11月9日电（记者刘白云 陈刚）据希腊国家广播电视公司9日报道，一艘移民船当天凌晨在该国南部克里特岛以南海域被发现，船上12人死亡。另据希腊海岸警卫队当天通报，在另一起救援行动中共发现8具遗体。 报道说，一艘货船在克里特岛以南海域发现这艘遇险船只。希腊海岸警卫队组织实施救援，救出18人，同时发现12具遗体。遇难者身份及具体死亡原因尚不清楚。 另据希腊海岸警卫队9日通报，克里特岛以南海域7日还发生一起移民船遇险事件，希腊海岸警卫…",
    "content": "新华社雅典11月9日电（记者刘白云 陈刚）据希腊国家广播电视公司9日报道，一艘移民船当天凌晨在该国南部克里特岛以南海域被发现，船上12人死亡。另据希腊海岸警卫队当天通报，在另一起救援行动中共发现8具遗体。 报道说，一艘货船在克里特岛以南海域发现这艘遇险船只。希腊海岸警卫队组织实施救援，救出18人，同时发现12具遗体。遇难者身份及具体死亡原因尚不清楚。 另据希腊海岸警卫队9日通报，克里特岛以南海域7日还发生一起移民船遇险事件，希腊海岸警卫队救出28人并发现一具遗体，但搜救行动因恶劣天气受阻。该移民船9日凌晨再次被发现…"
