    "content": "根据不同气候“定制”玉米品种、根据作物长势需求“定制”叶面喷剂……在第九届中国国际进口博览会上，各式各样的农业“定制化”创新成果集中亮相，农业创新正从通用产品向定制化转变。 种子是农业的“芯片”。我国地域辽阔，同一作物在不同地区面临的气候与病害挑战差异较大，一套种子难以通用全国。 “今年进博会上，我们带来8款迪卡玉米新品‘中国首发’。在西北春玉米区，茎腐病是影响产量的因素，品种迪卡2135茎腐抗性突出；黄淮海夏玉米区近年来遭遇灾害天气，易发南方锈病、茎腐病、穗腐病等，品种Q2402整体抗病性较强。”拜耳玉米种子合资…"
