    "content": "在正在举行的第九届中国国际进口博览会上，老朋友如期而至，新朋友纷至沓来。今年首次参加进博会的“新面孔”企业超2000家，全球首发、亚洲首展、中国首秀的代表性展品超过480件。 今年进博会上AI“浓度”最高的区域之一肯定是技术装备展区。在Hitch Open展台，两台全尺寸人形机器人隔着乒乓球桌相对而立，挥拍、击球、回位一气呵成。更热闹的是一旁等候体验的队伍，不少参观者早早排好队，就等着上场和机器人打一局。 Hitch Open全球执行主席唐敏勤表示，这是他们第一次参加进博会，带来的是具身智能、自主决策的乒乓球体验，…"
