    "pub_date": "2026-11-09 21:40:00",
    "author": "",
    "description": "香港与澳门，是近代以来中国人开眼看世界的两个重要窗口，更成为革命先驱求索真理、集结志士、筹谋救国的重要阵地。伟大的民族英雄、伟大的爱国主义者、中国民主革命的伟大先驱孙中山先生也曾在这里留下青春印记。 青年孙中山如何完成从“医人”到“医国”的转变？港澳两地青年，今天正以怎样的方式讲述孙中山的历史？在孙中山先生诞辰160周年之际，新华社推出四集微纪录片《在港澳，遇见青年孙中山》，追寻一代伟人的青春岁月，感悟跨越时空的家国情怀。 1923年2…",
