    "content": "新华社柏林11月9日电 德国总理、基民盟主席默茨9日正式提名巴伐利亚州议会议长伊尔泽·艾格纳竞选下任德国总统。如最终当选，艾格纳将成为德国历史上首位女性国家元首。 默茨在当天与艾格纳共同举行的新闻发布会上宣布了这一消息。默茨表示，在当前地缘政治危机交织、国内极端势力抬头的背景下，德国需要一位能够团结社会、为民众提供指引的总统。艾格纳政治经验丰富，且能够赢得广泛的社会共鸣。 艾格纳表示，自己未来将努力弥合社会分歧，坚决反对民粹主义和极端主义。 现年61岁的艾格纳来自德国基督教社会联盟（基社盟），其提名已获得德国主要政…"
