    "content": "（北京综合讯）随着A股进入宽幅调整，中国正采取一系列措施稳定股市，官方媒体称，摩根大通、高盛、瑞银等多家投行看好中国资产的配置价值。 据《证券日报》星期一（11月9日）报道，高盛亚洲团队近期发布报告称，看好中国国内人工智能（AI）相关股票，理由是估值已大幅压缩、政策支撑持续加码、外资机构仓位处于历史低位，认为从仓位角度来看，经历近期调整后，布局条件看来更具建设性。 报道引述摩根大通中国股票策略师张晓宁分析，本轮回调后，更多A股AI基础设施细分领域的风险回报比改善：晶圆制造设备和后道设备现已加入存储、服务器、交换机之…"
