    "pub_date": "2026-11-09 21:14:55",
    "author": "",
    "description": "中新网北京11月9日电 (记者 孙自法)第七届智库科学与工程国际研讨会11月8日至10日在北京举行，记者从会上获悉，由中国科学院科技战略咨询研究院院长潘教峰研究员牵头发起的“从证据到方案：人工智能驱动的政策模拟与情景分析”研究计划，2026年成功入选联合国“2024—2033年科学促进可持续发展国际十年”。",
    "content": "中新网北京11月9日电 (记者 孙自法)第七届智库科学与工程国际研讨会11月8日至10日在北京举行，记者从会上获悉，由中国科学院科技战略咨询研究院院长潘教峰研究员牵头发起的“从证据到方案：人工智能驱动的政策模拟与情景分析”研究计划，2026年成功入选联合国“2024—2033年科学促进可持续发展国际十年”。"
