    "description": "新华社东京11月9日电（记者李子越 梁晨 陈泽安）近期，日本电视剧《VIVANT》第二季因抹黑中国形象、煽动对华敌意引发巨大争议。日本有识之士对此提出强烈批评，但首相高市早苗等政府高官却声称“想看”“喜欢”。 近年来，在右翼保守势力推动下，日本政治和社会不断右倾化，右翼思想也越来越多在影视、文学、动漫等文艺作品中展现。这些“有毒”内容潜移默化地影响着日本民众的认知，使他们更倾向于接受修正主义历史叙事和扩军备武政策主张。在“投毒”时，日本…",
