    "content": "（北京综合讯）中国汽车出口10月保持稳健增长，但国内销量持续疲弱，车企开拓海外市场的压力进一步加大，海外市场竞争也可能随之加剧。 综合路透社、彭博社等报道，中国乘联分会星期一（11月9日）公布的数据显示，10月广义乘用车出口93万2000辆，同比大增68.2%，延续强劲增长势头。今年首10个月，中国汽车出口同比增长75%。 另一方面，尽管秋季是传统汽车销售旺季，10月中国国内汽车销量同比下滑27.3%至165万3000辆。这一跌幅较9月的28.1%略有收窄，但仍是连续第12个月下降。 分析认为，中国国内汽车市场今年…"
