    "description": "新华社德黑兰11月9日电（记者刁慧琳 沙达提）据伊朗伊斯兰共和国通讯社9日报道，伊朗军方发言人穆罕默德·阿克拉米-尼亚说，伊朗武装部队正在落实最高领袖近期指示，今后军事行动将更加注重快速回应和打击效果，且不再受地理范围限制。 阿克拉米-尼亚表示，最高领袖近期指示的重点包括“快速回应”，并提出“有效”和“不设地理限制”两项新要求。这些指示已成为伊朗武装部队采取行动的依据。伊朗此前的军事学说以防御和威慑为基础，而如今正向进攻性方向转变。 他…",
    "content": "新华社德黑兰11月9日电（记者刁慧琳 沙达提）据伊朗伊斯兰共和国通讯社9日报道，伊朗军方发言人穆罕默德·阿克拉米-尼亚说，伊朗武装部队正在落实最高领袖近期指示，今后军事行动将更加注重快速回应和打击效果，且不再受地理范围限制。 阿克拉米-尼亚表示，最高领袖近期指示的重点包括“快速回应”，并提出“有效”和“不设地理限制”两项新要求。这些指示已成为伊朗武装部队采取行动的依据。伊朗此前的军事学说以防御和威慑为基础，而如今正向进攻性方向转变。 他表示，伊朗不会因美国国内政治变化而放缓军事能力建设，将继续推进提升威慑能力计划。…"
