    "content": "新华社北京11月9日电 海湾阿拉伯国家合作委员会（海合会）六个成员国8日在巴林签署共建区域铁路项目协议，以推动建成连接海湾六国的铁路网络。该铁路网全长约1800公里，预计2030年12月投入运营。 这是2022年7月12日在沙特阿拉伯麦加拍摄的朝觐轻轨列车。新华社发 据阿拉伯联合酋长国《海湾新闻报》报道，海合会各成员国交通部门负责人当天签署了《海合会铁路项目总协议》。根据协议，阿联酋、阿曼、巴林、卡塔尔、科威特和沙特阿拉伯六国将共建全长1768公里的区域铁路网。 报道说，铁路网建成后，预计年客运量将从2030年约6…"
