    "content": "新华社北京11月9日电（记者梅常伟）全军学习贯彻党的二十届五中全会精神宣讲首场报告会9日在京举行。中共中央政治局委员、中央军委副主席张升民会见宣讲团成员。 张升民指出，党的二十届五中全会是在基本实现社会主义现代化关键时期召开的一次十分重要的会议，对于进一步开创新时代管党治党、兴党强党新局面具有重大意义。深入学习贯彻全会精神是当前和今后一个时期的重大政治任务，要按照党中央统一部署，深入学习领会习近平党建思想和习主席在全会上的重要讲话精神，围绕《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》重大部署、重要任务…"
