    "description": "新华社伊斯坦布尔11月9日电（记者王科文）土耳其西部伊兹密尔省省政府9日发表声明说，该省阿利阿区一座钢铁厂当天发生爆炸，造成6人死亡、13人受伤。 声明说，目前仍有8人被困，相关部门正全力开展搜救工作。初步调查显示，事故可能由一台起重机在铸钢过程中脱落并坠入电弧炉所致。",
    "content": "新华社伊斯坦布尔11月9日电（记者王科文）土耳其西部伊兹密尔省省政府9日发表声明说，该省阿利阿区一座钢铁厂当天发生爆炸，造成6人死亡、13人受伤。 声明说，目前仍有8人被困，相关部门正全力开展搜救工作。初步调查显示，事故可能由一台起重机在铸钢过程中脱落并坠入电弧炉所致。"
