    "author": "",
    "description": "“进博会对我们来说是每年最重要的一场展会，今年销售增长势头非常好。”来自意大利的珠宝商马可·卢梭说。这是他第8次来中国参加进博会，今年他还邀请了意大利的手工匠人同事，在现场展示贝雕技艺，吸引了很多观众驻足观看。 图为第九届进博会消费品展区的上海国际珠宝时尚功能区境外展团展位。新华社记者王辰阳 摄 记者在第九届进博会消费品展区看到，多位国际珠宝商集结在上海国际珠宝时尚功能区境外展团，带来彩色宝石、手工高级珠宝、收藏级钻石等展品。对他们来说…",
    "content": "“进博会对我们来说是每年最重要的一场展会，今年销售增长势头非常好。”来自意大利的珠宝商马可·卢梭说。这是他第8次来中国参加进博会，今年他还邀请了意大利的手工匠人同事，在现场展示贝雕技艺，吸引了很多观众驻足观看。 图为第九届进博会消费品展区的上海国际珠宝时尚功能区境外展团展位。新华社记者王辰阳 摄 记者在第九届进博会消费品展区看到，多位国际珠宝商集结在上海国际珠宝时尚功能区境外展团，带来彩色宝石、手工高级珠宝、收藏级钻石等展品。对他们来说，上海海关等部门创新的“进博直通车”业务，将珠光宝气延展至“四叶草”展馆内外。 …"
