    "content": "新华社布鲁塞尔11月9日电（记者 张兆卿）欧盟委员会主席冯德莱恩9日发表声明说，欧盟将参加本周在阿联酋首都阿布扎比举行的俄罗斯、美国、乌克兰三方会谈。 冯德莱恩在声明中说，她已与乌克兰总统泽连斯基通电话，讨论了“正在推进的和平努力”及本周的阿布扎比会谈。 泽连斯基当天在社交媒体发文表示，在与冯德莱恩通话中，双方就欧盟启动对乌紧急援助机制达成一致。 冯德莱恩还表示，她当天将与罗马尼亚和保加利亚两国领导人会晤，就地区局势及欧洲如何加强应对进行讨论。 美国总统特使威特科夫2日在社交媒体发文说，美方将于10日至11日在阿布…"
