    "content": "新华社上海11月9日电（记者杨有宗）第九届中国国际进口博览会“四叶草”展馆里，一处150平方米展台引人关注。31家来自上海张江科学城的“早小硬”科技企业组团亮相，平均不到5平方米就有一家硬科技企业，小空间里迸发出科创大能量。 “早小硬”指的是处于创业早期、体量规模尚小、深耕硬核技术研发的科技型企业，也是张江孵早、孵小、孵硬科技培育路径的核心服务对象。本届进博会是张江首次以“孵创展团”形式整体参展。 小展台高密度，硬科技可感可及。走进张江孵创展团，技术不再是实验室里的抽象概念，而是触手可及的应用场景。三指灵巧手精准演…"
