    "pub_date": "2026-11-09 20:10:31",
    "author": "",
    "description": "11月8日晚，由中央民族乐团创作出品的民族交响合唱《向光而行》在国家大剧院上演，这也是该剧目在北京首演。 《向光而行》是纪念红军长征胜利90周年、落实文化和旅游部主题创作部署的重点剧目，此前已先后在赣州、延安、西安完成演出，带着红色沃土的回响登上首都舞台。 全曲以“光”为核心意象，由序曲、六个乐章及尾声八个段落构成，沿着微光、火光、曙光、霞光、星光、荣光的脉络铺展叙事。 本次演出由中央民族乐团携手陕西省广播电视局、赣南师范大学共同主办，…",
    "content": "11月8日晚，由中央民族乐团创作出品的民族交响合唱《向光而行》在国家大剧院上演，这也是该剧目在北京首演。 《向光而行》是纪念红军长征胜利90周年、落实文化和旅游部主题创作部署的重点剧目，此前已先后在赣州、延安、西安完成演出，带着红色沃土的回响登上首都舞台。 全曲以“光”为核心意象，由序曲、六个乐章及尾声八个段落构成，沿着微光、火光、曙光、霞光、星光、荣光的脉络铺展叙事。 本次演出由中央民族乐团携手陕西省广播电视局、赣南师范大学共同主办，中央民族乐团、陕西省广播电视民族乐团、赣南师范大学、于都长征源合唱团联袂献演。 …"
