    "content": "新华社上海11月9日电 进博手记：“从乔卢特卡到上海，我们盼了整整三年” 新华社记者王诸苏 阚静文 第九届中国国际进口博览会的农产品展馆内，人流穿梭，洽谈声此起彼伏。来自洪都拉斯的迪亚娜·博尼利亚今年第一次站上进博会展台，但她毫不拘谨，热情地向驻足的客商介绍故乡的白虾养殖田。从中美洲的白虾养殖田到中国的展台，她跨越万里；为了让家乡的白虾走进更广阔的市场，她和家人奔忙了三年。 故事要从遥远的洪都拉斯城市乔卢特卡说起。乔卢特卡位于洪都拉斯南部，当地独特的红树林和火山土质环境，为水产养殖提供了得天独厚的条件，也赋予当地白…"
