    "description": "今年8月29日，六托盘英伟达货物从美国加利福尼亚州奥克兰出发，原定运往得克萨斯州沃思堡。按照当地媒体披露的调查信息，一辆印有食品运输公司标志的卡车按安排提走货物，途中曾多次停留；调查人员最后在加州南部的圣贝纳迪诺县失去车辆线索。报道所称案值为1140万美元。 买方在9月初发现货物没有送达，奥克兰警方确认于9月13日接到报案。直到11月初，这起案件才经媒体报道受到广泛关注。截至北京时间11月9日，警方尚未宣布逮捕嫌疑人。货物清单、具体失窃…",
    "content": "今年8月29日，六托盘英伟达货物从美国加利福尼亚州奥克兰出发，原定运往得克萨斯州沃思堡。按照当地媒体披露的调查信息，一辆印有食品运输公司标志的卡车按安排提走货物，途中曾多次停留；调查人员最后在加州南部的圣贝纳迪诺县失去车辆线索。报道所称案值为1140万美元。 买方在9月初发现货物没有送达，奥克兰警方确认于9月13日接到报案。直到11月初，这起案件才经媒体报道受到广泛关注。截至北京时间11月9日，警方尚未宣布逮捕嫌疑人。货物清单、具体失窃地点、承运方身份及设备去向，仍有待查明。 案件发生时，高价值计算设备正成为美国货…"
