    "description": "初冬时节，黑龙江省大庆市龙凤区黎明街道孙女士家中暖意融融。往年在家总要裹着厚棉衣，如今换上轻便家居服。这份触手可及的室内温度，源自城市地下看不见的供热管网，也是国家“六张网”建设中城市地下管网建设带来的民生实效。 从热源保障、管网巡检到智能运维，供热服务向精细化延伸。深埋地下的供热管线默默输送暖流，奔赴千家万户，把冬日寒意挡在门外，让居民收获实实在在的幸福感。 2023年至2025年，大庆市供热领域累计获批国债项目24个，争取国家政策资…",
    "content": "初冬时节，黑龙江省大庆市龙凤区黎明街道孙女士家中暖意融融。往年在家总要裹着厚棉衣，如今换上轻便家居服。这份触手可及的室内温度，源自城市地下看不见的供热管网，也是国家“六张网”建设中城市地下管网建设带来的民生实效。 从热源保障、管网巡检到智能运维，供热服务向精细化延伸。深埋地下的供热管线默默输送暖流，奔赴千家万户，把冬日寒意挡在门外，让居民收获实实在在的幸福感。 2023年至2025年，大庆市供热领域累计获批国债项目24个，争取国家政策资金6.92亿元，带动企业匹配资金1.25亿元，深入推进供热老旧管网更新，为全市地…"
