    "description": "新华社北京11月9日电（记者曹嘉玥、孙楠）外交部发言人郭嘉昆9日表示，中国率先批准《关于成立世界人工智能合作组织的协定》，体现了推进合作组织筹建进程的真诚意愿和坚定承诺。中方欢迎并期待更多国家加入世界人工智能合作组织，共同推动构建公正合理的全球人工智能治理体系。 当日例行记者会上，有记者问：我们注意到，第十四届全国人民代表大会常务委员会第二十五次会议决定批准《关于成立世界人工智能合作组织的协定》，发言人能否进一步介绍有关情况？ 郭嘉昆说…",
    "content": "新华社北京11月9日电（记者曹嘉玥、孙楠）外交部发言人郭嘉昆9日表示，中国率先批准《关于成立世界人工智能合作组织的协定》，体现了推进合作组织筹建进程的真诚意愿和坚定承诺。中方欢迎并期待更多国家加入世界人工智能合作组织，共同推动构建公正合理的全球人工智能治理体系。 当日例行记者会上，有记者问：我们注意到，第十四届全国人民代表大会常务委员会第二十五次会议决定批准《关于成立世界人工智能合作组织的协定》，发言人能否进一步介绍有关情况？ 郭嘉昆说，今年7月，习近平主席在2026世界人工智能大会暨人工智能全球治理高级别会议上宣…"
