    "description": "11月9日，国家统计局公布10月物价数据。 10月份，全国居民消费价格（CPI）同比上涨0.7%，环比持平。1—10月平均，全国居民消费价格比上年同期上涨0.9%。 10月份，全国工业生产者出厂价格（PPI）同比上涨5.7%，环比上涨0.7%。工业生产者购进价格同比上涨7.9%，环比上涨1.1%。1—10月平均，工业生产者出厂价格比上年同期上涨2.7%，工业生产者购进价格上涨4.0%。 食品价格同比降幅扩大，10月CPI同比增速回落 1…",
