    "content": "新华社北京11月9日电 商务部新闻发言人9日表示，根据《中华人民共和国反外国制裁法》《不可靠实体清单规定》及有关规定，不可靠实体清单工作机制于2025年4月4日发布公告，将11家美国实体列入不可靠实体清单，采取相应措施。为落实中美第八轮经贸磋商共识，中方决定自2026年11月10日起，继续暂停2025年4月4日公告相关措施2个月。 有记者问：有消息称，根据中美第八轮经贸磋商共识，中方将调整一批针对美国的非关税措施。请问在不可靠实体清单方面有什么考虑？ 发言人表示，根据《不可靠实体清单规定》相关规定，国内企业可申请与…"
