    "content": "新华社德黑兰11月9日电（记者刁慧琳 沙达提）伊朗外交部发言人巴加埃9日表示，美国从陆路围堵伊朗的“铁门”计划与其此前采取的其他封堵行动没有不同，必将以失败告终。 巴加埃当天在记者会上说：“我们知道他们此前采取过哪些行动。毫无疑问，他们的新行动也不会有不同的结局，最终只会再次以失败告终。” 巴加埃说，所谓“铁门”计划是美国军方一些官员提出的，他们在试图“弥补自己的失败”。他还嘲笑说，下令组建“铁门”特遣队的美军中央司令部司令库珀“似乎很快就要换工作了”。 美军中央司令部7日宣布组建一支“铁门”特遣队，由约20名文职…"
