    "description": "新华社土耳其安塔利亚11月9日电 《联合国气候变化框架公约》第三十一次缔约方大会开幕之际，世界气象组织9日发布报告指出，2026年，全球气温异常偏高、冰川融化及海平面上升的长期态势仍在持续。超强厄尔尼诺预计将进一步加剧高温与极端天气，其影响将持续至2027年。 报告显示，今年1月至9月，全球平均地表温度比工业化前平均水平高出约1.47摄氏度。受厄尔尼诺增暖效应影响，这一数值在年底前很可能继续上升。2026年将成为有记录以来最暖的4个年份…",
    "content": "新华社土耳其安塔利亚11月9日电 《联合国气候变化框架公约》第三十一次缔约方大会开幕之际，世界气象组织9日发布报告指出，2026年，全球气温异常偏高、冰川融化及海平面上升的长期态势仍在持续。超强厄尔尼诺预计将进一步加剧高温与极端天气，其影响将持续至2027年。 报告显示，今年1月至9月，全球平均地表温度比工业化前平均水平高出约1.47摄氏度。受厄尔尼诺增暖效应影响，这一数值在年底前很可能继续上升。2026年将成为有记录以来最暖的4个年份之一。 海平面与海洋热含量均创历史新高。海平面处于历史最高位，2026年期间海表…"
