    "title": "北京迎来入冬初雪 - November 9, 2026",
    "link": "https://m.idai.ly/se/32bXUs",
    "pub_date": "2026-11-09 17:59:00",
    "author": "",
    "description": "北京箭扣长城被白雪覆盖，中国。11月8日，北京迎来2026年冬季首场降雪，全市最低气温降至-3℃，延庆、怀柔、密云、门头沟等地区积雪深度达到2至10厘米。中央气象台当天发布寒潮蓝色预警，中国中东部地区出现大范围雨雪和强降温天气，局部地区降温幅度超过12℃，预计未来3天寒潮天气将继续影响至南方地区，上海、浙江、广东、福建等地将降温6至8℃。摄影师：iDaily Media",
