    "content": "新华社东京11月9日电（记者陈泽安 梁晨）据日本共同社9日报道，日本执政党自民党当天表示，针对前首相石破茂等4人在消费税减税相关法案表决前离场、未投赞成票，对他们给予警告处分。 另据日本《朝日新闻》报道，这是日本首次有前首相受到这一处分。 本月6日，日本国会众议院就高市早苗政府推动的消费税减税相关法案进行表决。尽管法案在众议院通过，但因存在未明确财源等问题遭到在野党和部分自民党议员反对。表决前，包括石破茂、前经济企划厅长官船田元、前法务大臣古川祯久以及自民党前选举对策委员长小渊优子在内的4名自民党议员中途退席，未参…"
