    "content": "初冬时节，黑土地尚未完全封冻，在产粮第一大省黑龙江，各地正抢农时推进秋整地。翻地、灭茬、起垄、秸秆还田接续作业，一块块刚收完的耕地被重新翻整，为明年春播打下基础。 在佳木斯市桦南县明义乡兴旺村，两台大马力拖拉机带着翻转犁进地，犁铧过后，玉米秸秆和根茬被粉碎，扣进土里，起垄机紧跟其后，黝黑的耕地上筑起了一条条大垄。村民李连生站在地头笑着说，今年春天他把家里90多亩旱田全部托管给村里的合作社，从春季备耕到秋后整地，全程都不用自己操心。“今年粮食卖了20多万元，比自己种效益高多了。”他说。 兴旺村是当地大垄密植模式示范区…"
